  "id": "p_001",
  "summary": "Propuesta para una API REST minimal en Python usando http.server estándar, con endpoints CRUD para tareas, respuestas JSON, y almacenamiento en memoria.",
  "approach": "Utilizar el módulo http.server de Python para implementar un servidor HTTP básico que maneje rutas manualmente. Definir un diccionario en memoria para almacenar tareas con IDs auto-incrementados. Implementar validación de entrada para los campos requeridos y el estado predefinido. Todas las respuestas incluirán el encabezado Content-Type: application/json y códigos de estado HTTP apropiados (200, 201, 204, 404, 400).",
  "tradeoffs": ["Almacenamiento en memoria: los datos se pierden al reiniciar el servidor, no adecuado para producción.", "Sin validación robusta: la validación es básica y no cubre todos los posibles errores de entrada.", "Sin autenticación: cualquier cliente puede modificar o eliminar tareas, lo que plantea riesgos de seguridad.", "Rendimiento limitado: el servidor es single-threaded y no está optimizado para alta concurrencia.", "Simplicidad vs. funcionalidad: el diseño es minimalista pero carece de características avanzadas como paginación o filtrado."],
  "evidence": ["Documentación oficial de Python para http.server: https://docs.python.org/3/library/http.server.html", "Principios REST descritos en el libro 'RESTful Web APIs' de Leonard Richardson y Mike Amundsen.", "Estándar HTTP/1.1 para códigos de estado: RFC 7231.", "Formato JSON definido en RFC 8259."],
  "artifacts": [
    {
      "kind": "server.py",
      "language": "python",
      "source": "import http.server
import json
from urllib.parse import urlparse
class TaskHandler(http.server.BaseHTTPRequestHandler):
    # Almacenamiento en memoria
    tasks = {}
    next_id = 1
    def _set_headers(self, status_code=200):
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
    def _send_json(self, data, status_code=200):
        self._set_headers(status_code)
        self.wfile.write(json.dumps(data).encode())
    def do_GET(self):
        parsed_path = urlparse(self.path)
        path = parsed_path.path
        if path == '/tasks':
            tasks_list = list(self.tasks.values())
            self._send_json(tasks_list, 200)
        elif path.startswith('/tasks/'):
            task_id = path.split('/')[-1]
            if task_id in self.tasks:
                self._send_json(self.tasks[task_id], 200)
            else:
                self._send_json({'error': 'Task not found'}, 404)
        else:
            self._send_json({'error': 'Not found'}, 404)
    def do_POST(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path == '/tasks':
            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length)
            try:
                data = json.loads(post_data)
                if not all(key in data for key in ['title', 'description', 'status']):
                    self._send_json({'error': 'Missing fields'}, 400)
                    return
                if data['status'] not in ['pendiente', 'en progreso', 'completada']:
                    self._send_json({'error': 'Invalid status'}, 400)
                    return
                task_id = str(self.next_id)
                self.next_id += 1
                task = {
                    'id': task_id,
                    'title': data['title'],
                    'description': data['description'],
                    'status': data['status']
                }
                self.tasks[task_id] = task
                self._send_json(task, 201)
            except json.JSONDecodeError:
                self._send_json({'error': 'Invalid JSON'}, 400)
        else:
            self._send_json({'error': 'Not found'}, 404)
    def do_PUT(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path.startswith('/tasks/'):
            task_id = parsed_path.path.split('/')[-1]
            if task_id in self.tasks:
                content_length = int(self.headers.get('Content-Length', 0))
                put_data = self.rfile.read(content_length)
                try:
                    data = json.loads(put_data)
                    if not all(key in data for key in ['title', 'description', 'status']):
                        self._send_json({'error': 'Missing fields'}, 400)
                        return
                    if data['status'] not in ['pendiente', 'en progreso', 'completada']:
                        self._send_json({'error': 'Invalid status'}, 400)
                        return
                    self.tasks[task_id].update({
                        'title': data['title'],
                        'description': data['description'],
                        'status': data['status']
                    })
                    self._send_json(self.tasks[task_id], 200)
                except json.JSONDecodeError:
                    self._send_json({'error': 'Invalid JSON'}, 400)
            else:
                self._send_json({'error': 'Task not found'}, 404)
        else:
            self._send_json({'error': 'Not found'}, 404)
    def do_DELETE(self):
        parsed_path = urlparse(self.path)
        if parsed_path.path.startswith('/tasks/'):
            task_id = parsed_path.path.split('/')[-1]
            if task_id in self.tasks:
                del self.tasks[task_id]
                self._set_headers(204)
                self.wfile.write(b'')
            else:
                self._send_json({'error': 'Task not found'}, 404)
        else:
            self._send_json({'error': 'Not found'}, 404)
def run(server_class=http.server.HTTPServer, handler_class=TaskHandler, port=8000):
    server_address = ('', port)
    httpd = server_class(server_address, handler_class)
    print(f'Starting server on port {port}')
    httpd.serve_forever()
if __name__ == '__main__':
    run()"
    }
